static long SizeOf(Func<object> make)
{
    make();  // warm-up: JIT and first allocations
    long before = GC.GetAllocatedBytesForCurrentThread();
    object o = make();
    long after = GC.GetAllocatedBytesForCurrentThread();
    GC.KeepAlive(o);
    return after - before;
}

